questionvariables.text:
/* Five false statements: [vnum, statement, hypothesis word, f(n), counterexample, second counterexample, value failing the hypothesis, agreeing value]. */
vbank: [
 [1, "Let \\(n\\) be an integer. If \\(n\\) is odd, then \\(n^2 + 4\\) is prime.", "odd", n^2 + 4, 9, 11, 2, 1],
 [2, "Let \\(n\\) be an integer. If \\(n\\) is odd, then \\(n^2 + 2\\) is prime.", "odd", n^2 + 2, 5, 7, 4, 3],
 [3, "Let \\(n\\) be an integer. If \\(n\\) is prime, then \\(2n + 1\\) is prime.", "prime", 2*n + 1, 7, 13, 4, 5],
 [4, "Let \\(n\\) be an integer. If \\(n\\) is even, then \\(n^2 + 1\\) is prime.", "even", n^2 + 1, 8, 0, 3, 2],
 [5, "Let \\(n\\) be an integer. If \\(n\\) is odd, then \\(n^2 + n + 1\\) is prime.", "odd", n^2 + n + 1, 7, -1, 4, 3]
];
vrec: rand(vbank);
vnum: vrec[1]; stmtC: vrec[2]; hypword: vrec[3]; hyp: vrec[3]; fexpr: vrec[4];
tce: vrec[5]; tce2: vrec[6]; tdiag: vrec[7]; tagree: vrec[8];
valce: ev(subst(n = tce, fexpr), simp);
hypholds(m) := if hyp = "odd" then oddp(m) else if hyp = "even" then evenp(m) else (is(m > 1) and primep(m));
validate_int(ex) := block([vv], vv: ev(ex, simp), if integerp(vv) then "" else "Enter a whole number.");
ta1: tce;
ta2: [[t_cex, false, "It shows that \\(n = 2\\) is a counterexample, so the statement is false and the proof in the example must contain a mistake."],
      [t_none, true, "It shows nothing about the statement: 2 is not odd, so the statement makes no claim about \\(n = 2\\)."],
      [t_conv, false, "It shows that the converse, ‘if \\(n^3 + 1\\) is even, then \\(n\\) is odd’, is false."],
      [t_some, false, "It shows that \\(n^3 + 1\\) is even for some odd numbers \\(n\\) but not for all of them."]];
s_assert(hypholds(tce) and not(primep(valce)), true);
s_assert(hypholds(tce2) and not(primep(ev(subst(n = tce2, fexpr), simp))), true);
s_assert(not(hypholds(tdiag)), true);
s_assert(not(hypholds(-tdiag)), true);
s_assert(hypholds(tagree) and primep(ev(subst(n = tagree, fexpr), simp)), true);

feedbackvariables.text:
val: ev(subst(n = ans1, fexpr), simp);
hok: hypholds(ans1);
cfails: not(is(val > 1) and primep(val));
sf: if is(val >= 4) and is(val < 10^12) then first(first(ifactors(val))) else 0;
